mapper.select:

SELECT COALESCE(brno,'') AS brno
FROM kids_own.TB_CM_M_ULD_PRST
WHERE ptcp_inst_sn = #{ptcpInstSn}
  AND pblnt_sn = #{pblntSn}
  AND (del_yn IS NULL OR TRIM(del_yn) = '' OR UPPER(TRIM(del_yn)) = 'N')
LIMIT 1

mapper.delete:
DELETE FROM kids_own.TB_CM_D_ULD_PRD_SCL
WHERE pblnt_sn = #{pblntSn}
  AND ptcp_inst_sn = #{ptcpInstSn}

DELETE FROM kids_own.TB_CM_M_ULD_CTLG
WHERE pblnt_sn = #{pblntSn}
  AND ptcp_inst_sn = #{ptcpInstSn}

mapper.select:
SELECT COALESCE(NULLIF(TRIM(uld_prgrs_yn), ''), 'N')
FROM kids_own.TB_CM_M_ULD_PRST
WHERE pblnt_sn = #{pblntSn}
  AND ptcp_inst_sn = #{ptcpInstSn}
  AND (del_yn IS NULL OR del_yn = 'N')
LIMIT 1

SELECT TRIM(COALESCE(NULLIF(TRIM(prst.inst_id), ''), NULLIF(TRIM(prst.brno), '')))
FROM kids_own.TB_CM_M_ULD_PRST prst
WHERE prst.ptcp_inst_sn = #{ptcpInstSn}
  AND prst.pblnt_sn = #{pblntSn}
  AND (prst.del_yn IS NULL OR prst.del_yn = 'N')
  AND (
    (prst.inst_id IS NOT NULL AND TRIM(prst.inst_id) != '')
    OR (prst.brno IS NOT NULL AND TRIM(prst.brno) != '')
  )
LIMIT 1
